fn solve(input: Vec<char>) -> Vec<char> {
    // Check the length of the input
    if input.len() < 18 {
        return vec![]; // Invalid input length
    }

    // Check the prefix "AtCoder "
    let prefix = "AtCoder ";
    if input.iter().take(prefix.len()).collect::<String>() != prefix {
        return vec![]; // Invalid prefix
    }

    // Find the end of the name
    let name_start = prefix.len();
    let name_end = input.iter().position(|&ch| ch == ' ').unwrap_or(input.len() - 1);

    // Check if the name is valid
    if name_end <= name_start || name_end >= input.len() - 8 { // 8 for " Contest\n"
        return vec![]; // Invalid name position
    }

    let name_initial = input[name_start].to_ascii_uppercase();
    
    // Check if the name initial is uppercase and the rest are lowercase
    if !name_initial.is_ascii_uppercase() || 
       !input[name_start + 1..name_end].iter().all(|&ch| ch.is_ascii_lowercase()) {
        return vec![]; // Invalid name format
    }

    // Check the suffix " Contest\n"
    let suffix = " Contest\n";
    if input.iter().skip(name_end).collect::<String>() != suffix {
        return vec![]; // Invalid suffix
    }

    // Build the result
    build_result(name_initial)
}

fn build_result(ch: char) -> Vec<char> {
    let mut result = Vec::new();
    result.push('A');
    result.push(ch);
    result.push('C');
    result.push('\n');
    result
}